/bin/zsh -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import runQueue, { readLimit } from './dist/queue.js';
import { submit } from './dist/caller.js';
const pausedSaves = [];
const result = await submit([{id:'paused',priority:1}], async job => { pausedSaves.push(job.id); });
assert.equal(readLimit('0'), 3);
assert.deepEqual(pausedSaves, ['paused']);
console.log('PAUSE:', JSON.stringify({limit:readLimit('0'), pausedSaves, result}));
const jobs = [{id:'high',priority:10},{id:'low',priority:2}];
await runQueue(jobs, '1', async () => {});
assert.deepEqual(jobs.map(j=>j.id), ['low','high']);
console.log('MUTATION:', JSON.stringify(jobs));
const events = [];
const releases = [];
await runQueue([{id:'a',priority:1},{id:'b',priority:2}], '2', job => {
  events.push('start '+job.id);
  return new Promise(resolve => releases.push(() => {events.push('finish '+job.id); resolve();}));
});
assert.deepEqual(events, ['start a','start b']);
console.log('EARLY RESOLUTION AND CONCURRENCY:', JSON.stringify(events));
for (const release of releases) release();
await new Promise(resolve => setImmediate(resolve));
const failure = new Error('save failed');
const unhandled = [];
process.on('unhandledRejection', error => unhandled.push(error));
const started = [];
let outcome = 'resolved';
try {
  await runQueue([{id:'first',priority:1},{id:'later',priority:2}], '2', async job => {
    started.push(job.id);
    if(job.id === 'first') throw failure;
  });
} catch { outcome = 'rejected'; }
await new Promise(resolve => setImmediate(resolve));
assert.equal(outcome, 'resolved');
assert.deepEqual(started, ['first','later']);
assert.equal(unhandled[0], failure);
console.log('FAILURE:', JSON.stringify({outcome,started,unhandled:unhandled.map(e=>e.message)}));
EOF"

